create function memocious_private.product_fields_base(sid uuid,pid uuid,fields jsonb) returns memocious.products language plpgsql security invoker set search_path='' as $$
declare p memocious.products;opt jsonb;val jsonb;optid uuid;n int:=0;j int;
begin perform memocious_private.assert_admin(sid);select * into p from memocious.products where id=pid for update;
 update memocious.products set name=coalesce(fields->>'name',name),slug=coalesce(fields->>'slug',slug),description=coalesce(fields->>'description',description),detail=coalesce(fields->>'detail',detail),price_paise=case when fields?'pricePaise' then (fields->>'pricePaise')::bigint else price_paise end,max_price_paise=case when fields?'maxPricePaise' then (fields->>'maxPricePaise')::bigint else max_price_paise end,materials=coalesce(fields->>'materials',materials),dimensions=coalesce(fields->>'dimensions',dimensions),colour=coalesce(fields->>'colour',colour),customizable=coalesce((fields->>'customizable')::boolean,customizable),featured=coalesce((fields->>'featured')::boolean,featured),in_stock=coalesce((fields->>'inStock')::boolean,in_stock),lead_type=coalesce(fields->>'lead',lead_type),lead_days=case when fields?'leadDays' then (fields->>'leadDays')::int else lead_days end,moq=case when fields?'moq' then (fields->>'moq')::int else moq end,enterprise=coalesce((fields->>'enterprise')::boolean,enterprise),seo_title=coalesce(fields->>'seoTitle',seo_title),seo_description=coalesce(fields->>'seoDescription',seo_description),message_limit=coalesce((fields->>'messageLimit')::int,message_limit),version=version+1,updated_at=now() where id=p.id returning * into p;
 if char_length(p.materials)>500 or char_length(p.dimensions)>300 or char_length(p.seo_title)>70 or char_length(p.seo_description)>160 or p.lead_days>365 then raise exception 'Invalid product details' using errcode='22023';end if;
 return p;
end $$;
revoke execute on function memocious_private.product_fields_base(uuid,uuid,jsonb) from public,anon,authenticated;grant execute on function memocious_private.product_fields_base(uuid,uuid,jsonb) to service_role;
